  values(v_release_id, 12, 'g12_st3', 10, 4, 'category', 'Phân loại đúng nhóm', 'Vận dụng nguyên tắc phát triển bền vững vào lựa chọn hành động địa phương.', '{"categories":["Hành động bền vững","Hành động không bền vững"],"items":["Tiết kiệm nước","Phân loại rác","Phục hồi sinh cảnh","Khai thác tận diệt"],"hint":"Dựa vào kiến thức của ải 10."}'::jsonb, '{"value":[{"name":"Tiết kiệm nước","catIndex":0},{"name":"Phân loại rác","catIndex":0},{"name":"Phục hồi sinh cảnh","catIndex":0},{"name":"Khai thác tận diệt","catIndex":1}],"explanation":"Tiết kiệm nước thuộc nhóm Hành động bền vững; Phân loại rác thuộc nhóm Hành động bền vững; Phục hồi sinh cảnh thuộc nhóm Hành động bền vững; Khai thác tận diệt thuộc nhóm Hành động không bền vững."}'::jsonb, '[{"source":"SGK Sinh học 12 - Kết nối tri thức với cuộc sống","publisher":"Nhà xuất bản Giáo dục Việt Nam","lesson":"Bài 34. Phát triển bền vững; Dự án bảo tồn sinh thái tại địa phương"}]'::jsonb);
  insert into public.station_content_items(release_id, grade, station_id, day_index, game_index, game_type, title, learning_objective, public_content, answer_key, source_refs)
